  7686  struct arth *
  7687  gen_arth(compiler_state_t *cstate, int code, struct arth *a0,
  7688      struct arth *a1)
  7689  {
  7690          struct slist *s0, *s1, *s2;
  7691
  7692          /*
  7693           * Catch errors reported by us and routines below us, and return NULL
  7694           * on an error.
  7695           */
  7696          if (setjmp(cstate->top_ctx))
  7697                  return (NULL);
  7698
  7699          /*
  7700           * Disallow division by, or modulus by, zero; we do this here
  7701           * so that it gets done even if the optimizer is disabled.
  7702           *
  7703           * Also disallow shifts by a value greater than 31; we do this
  7704           * here, for the same reason.
  7705           */
  7706          if (code == BPF_DIV) {
  7707                  if (a1->s->s.code == (BPF_LD|BPF_IMM) && a1->s->s.k == 0)
  7708                          bpf_error(cstate, "division by zero");
  7709          } else if (code == BPF_MOD) {
  7710                  if (a1->s->s.code == (BPF_LD|BPF_IMM) && a1->s->s.k == 0)
  7711                          bpf_error(cstate, "modulus by zero");
  7712          } else if (code == BPF_LSH || code == BPF_RSH) {
  7713                  /*
  7714                   * XXX - we need to make up our minds as to what integers
  7715                   * are signed and what integers are unsigned in BPF programs
  7716                   * and in our IR.
  7717                   */
  7718                  if (a1->s->s.code == (BPF_LD|BPF_IMM) &&
  7719                      (a1->s->s.k < 0 || a1->s->s.k > 31))
  7720                          bpf_error(cstate, "shift by more than 31 bits");
  7721          }
  7722          s0 = xfer_to_x(cstate, a1);
  7723          s1 = xfer_to_a(cstate, a0);
  7724          s2 = new_stmt(cstate, BPF_ALU|BPF_X|code);
  7725
  7726          sappend(s1, s2);
  7727          sappend(s0, s1);
  7728          sappend(a1->s, s0);
  7729          sappend(a0->s, a1->s);
  7730
  7731          free_reg(cstate, a0->regno);
  7732          free_reg(cstate, a1->regno);
  7733
  7734          s0 = new_stmt(cstate, BPF_ST);
  7735          a0->regno = s0->s.k = alloc_reg(cstate);
  7736          sappend(a0->s, s0);
  7737
  7738          return a0;
  7739  }
