  7751  /*
  7752   * Return the next free register.
  7753   */
  7754  static int
  7755  alloc_reg(compiler_state_t *cstate)
  7756  {
  7757          int n = BPF_MEMWORDS;
  7758
  7759          while (--n >= 0) {
  7760                  if (cstate->regused[cstate->curreg])
  7761                          cstate->curreg = (cstate->curreg + 1) % BPF_MEMWORDS;
  7762                  else {
  7763                          cstate->regused[cstate->curreg] = 1;
  7764                          return cstate->curreg;
  7765                  }
